import {sequenceBrief} from './studio-lab-model.js';
export function translateTruth(n,s,language){
 if(!['es','pt'].includes(language))return n;const es=language==='es',m=n.audit.reading.metrics,b=sequenceBrief(s,n.time,{language,corrected:n.revision===2});
 const context={...n.context,question:({wide:es?'¿La carrera realmente movió al defensor?':'A corrida realmente deslocou o defensor?',press:es?'¿La presión causó la recuperación?':'A pressão causou a recuperação?',counter:es?'¿Un buen ataque garantiza un gol?':'Um bom ataque garante um gol?'})[s.id]};
 const labels=es?{Observe:'Observa','The claim':'La afirmación',Challenge:'Cuestiona','The outcome':'El resultado','The recovery':'La recuperación','The transition':'La transición'}:{Observe:'Observe','The claim':'A afirmação',Challenge:'Questione','The outcome':'O resultado','The recovery':'A recuperação','The transition':'A transição'};
 const originalLine=n.ready?(es?`Laurent se desplazó ${m.lateral.toFixed(1)} m hacia la banda de Moreau.`:`Laurent se deslocou ${m.lateral.toFixed(1)} m para a lateral de Moreau.`):(es?'Todavía no se afirma un desplazamiento.':'Ainda não há afirmação de deslocamento.');
 const currentLine=n.changed?(es?'El registro corregido no muestra movimiento lateral de Laurent.':'O registro corrigido não mostra movimento lateral de Laurent.'):originalLine;
 const headline=n.changed?(es?'La carrera sigue. La afirmación cambia.':'A corrida continua. A afirmação muda.'):n.resolved?(es?'El resultado está en el registro.':'O resultado está no registro.'):n.ready?(es?'Una observación. Una explicación por comprobar.':'Uma observação. Uma explicação a verificar.'):(es?'Primero, observa la jugada.':'Primeiro, observe a jogada.');
 const factLine=`Harbor: ${m.completed}/${m.passes} ${es?'pases completados':'passes completos'}. ${m.goals} ${es?'goles registrados':'gols registrados'}.`;
 const observation=(n.audience==='analyst'?factLine+' ':'')+b.cards.find(c=>c.id==='analyst').text;
 const interpretation=es?'La coincidencia o el orden de los eventos no demuestra una causa. La explicación debe respetar el registro actual.':'A coincidência ou a ordem dos eventos não prova uma causa. A explicação deve respeitar o registro atual.';
 const review=n.changed?(es?'Retira únicamente la afirmación de movimiento. Los pases y los disparos conservan su evidencia.':'Retire apenas a afirmação de movimento. Os passes e chutes mantêm sua evidência.'):(es?'Mantén los hechos observados. Presenta la explicación táctica como una interpretación, no como una causa probada.':'Mantenha os fatos observados. Apresente a explicação tática como interpretação, não como causa comprovada.');
 const outcome=n.resolved?(s.id==='counter'?(es?'Resultado registrado: Berg detiene el tiro. Sigue el 0–0.':'Resultado registrado: Berg defende. O placar segue 0–0.'):(es?'Resultado registrado: gol de Brooks. El evento de gol sigue siendo válido.':'Resultado registrado: gol de Brooks. O evento de gol continua válido.')):(es?'El resultado final del disparo queda fuera de este límite de evidencia.':'O resultado final do chute está além deste limite de evidência.');
 return {...n,context,headline,observation,interpretation,review,outcome,factLine,originalLine:s.id==='wide'?originalLine:observation,currentLine:s.id==='wide'?currentLine:observation,chapters:n.chapters.map(c=>({...c,label:labels[c.label]})),phase:n.changed?(es?'Revisado':'Revisado'):n.resolved?(es?'Resultado comprobado':'Resultado verificado'):n.ready?(es?'En revisión':'Em revisão'):(es?'Recopilando evidencia':'Reunindo evidências')};
}
